function configurationComparison(){
 const fieldLabel=k=>{const names={sku:'Catalogue model',kind:'Request type',goal:'Buyer priority',orderQty:'Order quantity',orderUnit:'Order unit',annualQty:'Annual planning volume',annualYear:'Forecast year / period',sampleQty:'Sample quantity',sampleUnit:'Sample unit',sampleUse:'Sample purpose',sampleArrival:'Sample arrival',market:'Destination market',ship:'Requested shipment',receive:'Requested receipt',launch:'Market launch',evaluation:'Evaluation deadline',assembly:'Assembly condition',size:'Size reference',notes:'Other requirements',idea:'New concept',referenceURL:'Reference URL',files:'Attachment filenames',referenceId:'Package reference',referenceVersion:'Version',title:'Promotion',terms:'Promotion terms',validFrom:'Valid from',validUntil:'Valid until',eligibility:'Pending confirmation',material:'Material family',grade:'Requested grade',scale:'Hardness scale',min:'Target minimum',max:'Target maximum',process:'Processing request',status:'Information basis',interfaceSize:'Mating size',interfaceStandard:'Standard / counterpart',dimensionUnit:'Dimension unit',label:'Component reference',mode:'Starting basis',format:'Single-item format',printing:'Printing / artwork',barcode:'Barcode',display:'Retail display',inner:'Inner box / set',outer:'Shipping carton',pallet:'Pallet preference',supply:'Supply responsibility',container:'Expected container',consolidation:'Full-container consolidation'};const keys=k.split('.');return (keys[0]==='components'?({blade:'Working part',grip:'Handle / grip',interface:'Connection / joint'}[keys[1]]||'Component')+' · ':keys[0]==='pack'?'Packaging · ':keys[0]==='logistics'?'Logistics · ':'')+(names[keys.at(-1)]||'Buyer requirement');};
 const a=lines.find(l=>l.id===s.compareA)||lines.find(l=>l.kind!=='standard')||lines[0],b=lines.find(l=>l.id===s.compareB&&l.id!==a?.id)||lines.find(l=>l.id!==a?.id&&l.kind!=='standard')||lines.find(l=>l.id!==a?.id);
 const options=id=>lines.map(l=>'<option value="'+l.id+'"'+(l.id===id?' selected':'')+'>'+esc(l.id+' · '+l.sku+' · v'+l.version)+'</option>').join('');
 const flatten=(o,prefix='')=>Object.entries(o).flatMap(([k,v])=>['id','version','changes','parent'].includes(k)?[]:v&&typeof v==='object'&&!Array.isArray(v)?flatten(v,prefix+k+'.'):[[prefix+k,Array.isArray(v)?v.map(f=>f.name).join(', '):v]]);
 const rows=a&&b?flatten(a).map(([k,v])=>{const other=get(b,k),value=Array.isArray(other)?other.map(f=>f.name).join(', '):other;return '<tr class="'+(v!==value?'diff':'')+'"><th>'+esc(fieldLabel(k))+'</th><td>'+esc(v||'open')+'</td><td>'+esc(value||'open')+'</td></tr>';}).join(''):'';
 return '<div class="a2-help"><section class="help-card" role="dialog" aria-modal="true" aria-label="Compare saved configurations" tabindex="-1"><div class="help-head"><h2>Compare saved configurations</h2>'+button('Close','helpclose','quiet')+'</div>'+(b?'<div class="fields two"><label class="field">First configuration<select id="be-compare-a">'+options(a.id)+'</select></label><label class="field">Second configuration<select id="be-compare-b">'+options(b.id)+'</select></label></div><table class="compare-table"><thead><tr><th>Buyer requirement</th><th>'+a.id+' · v'+a.version+'</th><th>'+b.id+' · v'+b.version+'</th></tr></thead><tbody>'+rows+'</tbody></table>':'<p>Add or copy a second configuration first. No engineering, price or compatibility assessment is inferred.</p>')+'<p>Highlighted differences are buyer inputs only; technical feasibility and commercial terms remain to be confirmed.</p>'+button('Return · keep choices','helpclose','primary')+'</section></div>';
}
host.addEventListener('change',e=>{if(e.target.id==='be-compare-a'||e.target.id==='be-compare-b'){s[e.target.id==='be-compare-a'?'compareA':'compareB']=e.target.value;render();}});
function uiText(value,depth=0){
 const dict=window.BL_ENQUIRY_LABELS?.[lang()]||{};if(dict[value]){const translated=dict[value];return dict[translated]&&dict[translated]!==translated?dict[translated]:translated;}if(depth>5||lang()==='en')return value;
 const tr=v=>uiText(v,depth+1);let m;
 if((m=value.match(/^Tab save expires in about (\d+) minutes\. Editing renews it, or keep it for another 30 minutes\.$/)))return tr('Tab save expires in about {minutes} minutes. Editing renews it, or keep it for another 30 minutes.').replace('{minutes}',m[1]);
 if((m=value.match(/^(\d+) (models|stable lines)(.*)$/)))return m[1]+' '+tr(m[2])+tr(m[3]);
 if((m=value.match(/^(\d+ · |← |Next → |e\.g\. )(.*)$/)))return (m[1]==='Next → '?tr('Next')+' → ':m[1]==='e.g. '?tr('e.g.')+' ':m[1])+tr(m[2]);
 if((m=value.match(/^(.*) (\(optional\)|\(if applicable\))$/)))return tr(m[1])+' ('+tr(m[2]==='(optional)'?'Optional':'if applicable')+')';
 if((m=value.match(/^(.*) ↗$/)))return tr(m[1])+' ↗';
 if((m=value.match(/^(L\d+)( standard reference added\.| saved as v\d+| independent copy of L\d+| restored with original version\.| saved · requests still pending review\.)$/)))return m[1]+m[2].replace(/standard reference added\.|saved as|independent copy of|restored with original version\.|requests still pending review\.|saved/g,k=>tr(k));
 if((m=value.match(/^(blade|grip|interface) (hardness range|hardness scale|processing|hardness)$/)))return tr({blade:'Working part',grip:'Handle / grip',interface:'Connection / joint'}[m[1]])+' · '+tr(m[2]);
 if((m=value.match(/^(.*) material changed\.$/)))return tr(m[1])+' · '+tr('changed');
 // Only structural UI delimiters are composed. Data, model IDs and source titles remain intact.
 if(value.includes(' · '))return value.split(' · ').map(tr).join(' · ');
 if(value.includes(' / '))return value.split(' / ').map(tr).join(' / ');
 if((m=value.match(/^(Catalogue evidence|PDF page|Sizes|Checked|Source|Applicable basis|Order|Engineering|Destination market): (.*)$/))){return tr(m[1])+': '+tr(m[2]);}
 if((m=value.match(/^(PDF page) (\d+)$/)))return tr(m[1])+' '+m[2];
 if((m=value.match(/^(.*), PDF page (\d+)\. Sizes: (.*?)\. (Other dimensions may be requested; availability is not implied\.)$/)))return m[1]+', '+tr('PDF page')+' '+m[2]+'. '+tr('Sizes')+': '+m[3]+'. '+tr(m[4]);
 if((m=value.match(/^(.*?)\. (These are independent reference Apps, not product-sales forecasts or supply commitments\.)$/)))return tr(m[1])+'. '+tr(m[2]);
 if((m=value.match(/^(edit) (v\d+)$/)))return tr(m[1])+' '+m[2];
 if((m=value.match(/^(To confirm) ([?–—\d.-]+)$/)))return tr(m[1])+' '+m[2];
 if((m=value.match(/^(.*?) (unit open|To confirm)(.*)$/)))return tr(m[1])+' '+tr(m[2])+tr(m[3]);
 return value;
}
function translateUI(root=host){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement.closest('textarea,[readonly],.rfq'))continue;const value=node.nodeValue.trim(),translated=uiText(value);if(translated!==value){if(node.parentElement.tagName==='OPTION'&&!node.parentElement.hasAttribute('value'))node.parentElement.value=value;node.nodeValue=node.nodeValue.replace(value,translated);}}
 for(const element of root.querySelectorAll('[placeholder],[aria-label]'))for(const attribute of ['placeholder','aria-label'])if(element.hasAttribute(attribute))element.setAttribute(attribute,uiText(element.getAttribute(attribute)));
 if(root===host){const bar=(document.getElementById('app-bar')||document.querySelector('.bj-nav'))?.getBoundingClientRect(),dockElement=document.querySelector('.ab-dock'),dock=dockElement?.getBoundingClientRect();const bottomDock=dockElement&&getComputedStyle(dockElement).position==='fixed'&&dock.top>=innerHeight/2&&dock.top<innerHeight;host.style.setProperty('--be-overlay-top',Math.max(65,bar&&bar.bottom>0&&bar.bottom<innerHeight/3?bar.bottom+8:65)+'px');host.style.setProperty('--be-overlay-bottom',(bottomDock?innerHeight-dock.top+8:12)+'px');}
}
