 badge.classList.toggle('be-draft-warning',!!active&&(!storageOK||draftExpired||minutes<=5));badge.innerHTML='<p role="status">'+esc(uiText(text))+'</p>'+ (active&&(!storageOK||draftExpired||minutes<=5)?button(zh?'再保留 30 分鐘':uiText('Keep for another 30 minutes'),'renew')+button(zh?'下載完整草稿':uiText('Download full draft'),'draftdownload'):'');
